    public void handleMyTrades(Client client, Map<String, Object> message)
    {
        //
        // {
        //   "channel": "account_trades",
        //   "data": [
        //     {
        //       "h": 80063441, // history id
        //       "i": 1559912767, // oid
        //       "I": null, // cloid
        //       "u": "BrZp5bidJ3WUvceSq7X78bhjTfZXeezzGvGEV4hAYKTa", // account address
        //       "s": "BTC",  // symbol
        //       "p": "89477", // price
        //       "o": "89505", // entry price
        //       "a": "0.00036", // amount
        //       "te": "fulfill_taker",
        //       "ts": "close_long",
        //       "tc": "normal", // trade type
        //       "f": "0.012885", // fee
        //       "n": "-0.022965", // pnl
        //       "t": 1765018588190,
        //       "li": 1559912767
        //     }
        //   ]
        // }
        //
        if (java.util.Objects.equals(this.myTrades, null))
        {
            Long limit = this.safeInteger(this.options, "tradesLimit", 1000);
            this.myTrades = new ArrayCache.ArrayCacheBySymbolById(((Number)limit).intValue());
        }
        io.github.ccxt.ws.ArrayCache trades = (io.github.ccxt.ws.ArrayCache) this.myTrades;
        Map<String, Object> symbols = new HashMap<String, Object>() {{}};
        List<Object> data = (List<Object>) this.safeList(message, "data", new ArrayList<Object>(Arrays.asList()));
        Integer dataLength = ((List<?>)data).size();
        if (java.util.Objects.equals(dataLength, 0))
        {
            return;
        }
        for (var i = 0; i < ((List<?>)data).size(); i++)
        {
            Object rawTrade = (data == null || i < 0 || i >= data.size() ? null : data.get(i));
            Map<String, Object> parsed = this.parseWsTrade((Map<String, Object>) (rawTrade));
            String symbol = (String) ((Map<String, Object>)parsed).get("symbol");
            if (!java.util.Objects.equals(symbol, null))
            {
                symbols.put((String)symbol, true);
            }
            trades.append(parsed);
        }
        List<Object> keys = new ArrayList<Object>(symbols.keySet());
        for (var i = 0; i < ((List<?>)keys).size(); i++)
        {
            String currentMessageHash = ("myTrades:" + (keys == null || i < 0 || i >= keys.size() ? null : keys.get(i)));
            client.resolve(trades, currentMessageHash);
        }
        // non-symbol specific
        String messageHash = "myTrades";
        client.resolve(trades, messageHash);
    }

